import { computed, defineComponent, h, inject, nextTick, onMounted, provide, ref, watch, Teleport, type ComputedRef, type InjectionKey, type Ref } from 'vue';
import { getNavigationMenuActiveState, getNavigationMenuState, navigationMenuStyleKeys } from '../lib/core';
import styles from './navigation-menu.module.scss';

interface NavigationMenuContextValue {
	activeValue: string | undefined;
	setActiveValue: (value: string | undefined) => void;
	viewportEnabled: boolean;
	viewportRef: Ref<HTMLDivElement | null>;
	setIndicatorRect: (rect: { left: number; width: number } | null) => void;
	indicatorRect: { left: number; width: number } | null;
}

type NavigationMenuContext = ComputedRef<NavigationMenuContextValue>;

const NavigationMenuContextKey: InjectionKey<NavigationMenuContext> = Symbol('tile-navigation-menu');

interface NavigationMenuItemContextValue {
	value: string;
	isActive: boolean;
	triggerRef: Ref<HTMLButtonElement | null>;
}

type NavigationMenuItemContext = ComputedRef<NavigationMenuItemContextValue>;

const NavigationMenuItemContextKey: InjectionKey<NavigationMenuItemContext> = Symbol('tile-navigation-menu-item');

function useNavigationMenuContext(): NavigationMenuContext {
	const context = inject(NavigationMenuContextKey);
	if (!context) {
		throw new Error('NavigationMenu 子组件必须位于 <NavigationMenu> 内部。');
	}
	return context;
}

function useNavigationMenuItemContext(): NavigationMenuItemContext {
	const context = inject(NavigationMenuItemContextKey);
	if (!context) {
		throw new Error('NavigationMenu 触发器/内容必须位于 <NavigationMenuItem> 内部。');
	}
	return context;
}

function navigationMenuChevronIcon() {
	return h(
		'svg',
		{
			class: styles[navigationMenuStyleKeys.chevron],
			xmlns: 'http://www.w3.org/2000/svg',
			width: '16',
			height: '16',
			viewBox: '0 0 24 24',
			fill: 'none',
			stroke: 'currentColor',
			'stroke-width': '2',
			'stroke-linecap': 'round',
			'stroke-linejoin': 'round',
			'aria-hidden': 'true',
		},
		[h('path', { d: 'm6 9 6 6 6-6' })],
	);
}

export const NavigationMenu = defineComponent({
	name: 'NavigationMenu',
	props: {
		viewport: { type: Boolean, default: true },
		value: { type: String, default: undefined },
		defaultValue: { type: String, default: undefined },
	},
	emits: ['update:value'],
	setup(props, { emit, slots, attrs }) {
		const internalValue = ref(props.defaultValue);
		const activeValue = computed(() => (props.value !== undefined ? props.value : internalValue.value));
		const viewportRef = ref<HTMLDivElement | null>(null);
		const indicatorRect = ref<{ left: number; width: number } | null>(null);

		function setActiveValue(next: string | undefined) {
			if (props.value === undefined) {
				internalValue.value = next;
			}
			emit('update:value', next);
		}

		function setIndicatorRect(next: { left: number; width: number } | null) {
			indicatorRect.value = next;
		}

		const context = computed<NavigationMenuContextValue>(() => ({
			activeValue: activeValue.value,
			setActiveValue,
			viewportEnabled: props.viewport,
			viewportRef,
			setIndicatorRect,
			indicatorRect: indicatorRect.value,
		}));

		provide(NavigationMenuContextKey, context);

		return () =>
			h('nav', { ...attrs, 'data-viewport': props.viewport, class: [styles[navigationMenuStyleKeys.root], attrs.class] }, [
				...(slots.default?.() ?? []),
				props.viewport ? h(NavigationMenuViewport) : null,
			]);
	},
});

export const NavigationMenuList = defineComponent({
	name: 'NavigationMenuList',
	setup(_props, { slots, attrs }) {
		function handleKeydown(event: KeyboardEvent) {
			const isNext = event.key === 'ArrowRight';
			const isPrev = event.key === 'ArrowLeft';
			const isHome = event.key === 'Home';
			const isEnd = event.key === 'End';
			if (!isNext && !isPrev && !isHome && !isEnd) {
				return;
			}

			const root = event.currentTarget as HTMLElement;
			const triggers = Array.from(root.querySelectorAll<HTMLButtonElement>('button')).filter((button) => !button.disabled);
			if (triggers.length === 0) {
				return;
			}

			const currentIndex = triggers.indexOf(document.activeElement as HTMLButtonElement);
			let nextIndex: number;
			if (isHome) {
				nextIndex = 0;
			} else if (isEnd) {
				nextIndex = triggers.length - 1;
			} else {
				const direction = isNext ? 1 : -1;
				nextIndex = (currentIndex + direction + triggers.length) % triggers.length;
			}

			triggers[nextIndex]?.focus();
			event.preventDefault();
		}

		return () => h('ul', { ...attrs, onKeydown: handleKeydown, class: [styles[navigationMenuStyleKeys.list], attrs.class] }, slots.default?.());
	},
});

export const NavigationMenuItem = defineComponent({
	name: 'NavigationMenuItem',
	props: {
		value: { type: String, required: true },
	},
	setup(props, { slots, attrs }) {
		const context = useNavigationMenuContext();
		const triggerRef = ref<HTMLButtonElement | null>(null);
		const isActive = computed(() => context.value.activeValue === props.value);

		const itemContext = computed<NavigationMenuItemContextValue>(() => ({ value: props.value, isActive: isActive.value, triggerRef }));

		provide(NavigationMenuItemContextKey, itemContext);

		return () => h('li', { ...attrs, class: [styles[navigationMenuStyleKeys.item], attrs.class] }, slots.default?.());
	},
});

export const NavigationMenuTrigger = defineComponent({
	name: 'NavigationMenuTrigger',
	inheritAttrs: false,
	setup(_props, { slots, attrs }) {
		const context = useNavigationMenuContext();
		const item = useNavigationMenuItemContext();

		function handleClick() {
			context.value.setActiveValue(item.value.isActive ? undefined : item.value.value);
		}

		function handleMouseEnter() {
			context.value.setActiveValue(item.value.value);
		}

		onMounted(() => {
			if (item.value.isActive) {
				nextTick(() => {
					const trigger = item.value.triggerRef.value;
					if (!trigger) {
						return;
					}
					const root = trigger.closest('nav');
					const rootRect = root?.getBoundingClientRect();
					const triggerRect = trigger.getBoundingClientRect();
					if (!rootRect) {
						return;
					}
					context.value.setIndicatorRect({ left: triggerRect.left - rootRect.left, width: triggerRect.width });
				});
			}
		});

		watch(
			() => item.value.isActive,
			(isActive) => {
				if (isActive) {
					nextTick(() => {
						const trigger = item.value.triggerRef.value;
						if (!trigger) {
							return;
						}
						const root = trigger.closest('nav');
						const rootRect = root?.getBoundingClientRect();
						const triggerRect = trigger.getBoundingClientRect();
						if (!rootRect) {
							return;
						}
						context.value.setIndicatorRect({ left: triggerRect.left - rootRect.left, width: triggerRect.width });
					});
				}
			},
		);

		return () =>
			h(
				'button',
				{
					...attrs,
					ref: item.value.triggerRef,
					type: 'button',
					'aria-expanded': item.value.isActive,
					'data-state': getNavigationMenuState(item.value.isActive),
					class: [styles[navigationMenuStyleKeys.trigger], attrs.class],
					onClick: handleClick,
					onMouseenter: handleMouseEnter,
				},
				[...(slots.default?.() ?? []), navigationMenuChevronIcon()],
			);
	},
});

export const NavigationMenuContent = defineComponent({
	name: 'NavigationMenuContent',
	inheritAttrs: false,
	setup(_props, { slots, attrs }) {
		const context = useNavigationMenuContext();
		const item = useNavigationMenuItemContext();

		return () => {
			const isActive = item.value.isActive;
			const content = h(
				'div',
				{
					...attrs,
					'data-state': getNavigationMenuState(isActive),
					'data-viewport': context.value.viewportEnabled,
					class: [styles[navigationMenuStyleKeys.content], attrs.class],
				},
				slots.default?.(),
			);

			if (!context.value.viewportEnabled) {
				return isActive ? content : null;
			}

			if (!context.value.viewportRef.value) {
				return null;
			}

			return isActive ? h(Teleport, { to: context.value.viewportRef.value }, [content]) : null;
		};
	},
});

export const NavigationMenuViewport = defineComponent({
	name: 'NavigationMenuViewport',
	inheritAttrs: false,
	setup(_props, { slots, attrs }) {
		const context = useNavigationMenuContext();

		return () =>
			h('div', { ...attrs, 'data-state': getNavigationMenuState(context.value.activeValue !== undefined), class: [styles[navigationMenuStyleKeys.viewport], attrs.class] }, [
				h('div', { ref: context.value.viewportRef, class: styles[navigationMenuStyleKeys.viewportInner] }, slots.default?.()),
			]);
	},
});

export const NavigationMenuIndicator = defineComponent({
	name: 'NavigationMenuIndicator',
	inheritAttrs: false,
	setup(_props, { attrs }) {
		const context = useNavigationMenuContext();

		return () => {
			const visible = context.value.indicatorRect !== null;
			const indicatorStyle = context.value.indicatorRect ? { left: `${context.value.indicatorRect.left}px`, width: `${context.value.indicatorRect.width}px` } : undefined;

			return h(
				'div',
				{
					...attrs,
					'data-state': visible ? 'visible' : 'hidden',
					class: [styles[navigationMenuStyleKeys.indicator], attrs.class],
					style: indicatorStyle,
				},
				[h('div', { class: styles[navigationMenuStyleKeys.indicatorArrow] })],
			);
		};
	},
});

export const NavigationMenuLink = defineComponent({
	name: 'NavigationMenuLink',
	inheritAttrs: false,
	props: {
		active: { type: Boolean, default: false },
		asChild: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		return () => {
			if (props.asChild) {
				const child = slots.default?.()[0];
				if (child) {
					const childProps = (child.props ?? {}) as Record<string, unknown>;
					return h(child, { ...childProps, 'data-active': getNavigationMenuActiveState(props.active) });
				}
			}

			return h('a', { ...attrs, 'data-active': getNavigationMenuActiveState(props.active), class: [styles[navigationMenuStyleKeys.link], attrs.class] }, slots.default?.());
		};
	},
});

export default NavigationMenu;

@use '../../../styles/variables/colors' as *;

// 根容器
.root {
	position: relative;
	display: flex;
	max-width: max-content;
	flex: 1;
	align-items: center;
	justify-content: center;
}

// 列表容器
.list {
	display: flex;
	flex: 1;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	list-style: none;
	margin: 0;
	padding: 0;
}

// 单个菜单项
.item {
	position: relative;
}

// 触发器按钮
.trigger {
	display: inline-flex;
	height: var(--tile-navigation-height, 2.25rem);
	width: max-content;
	align-items: center;
	justify-content: center;
	gap: $spacing-1;
	border-radius: var(--tile-navigation-trigger-radius, $radius);
	background-color: var(--tile-navigation-background, $background);
	padding: var(--tile-navigation-trigger-padding, $spacing-2 $spacing-4);
	font-size: var(--tile-navigation-font-size, $text-sm);
	font-weight: $font-medium;
	color: var(--tile-navigation-foreground, $foreground);
	outline: none;
	transition:
		background-color $transition-fast,
		color $transition-fast;
	cursor: pointer;

	&:hover {
		background-color: var(--tile-navigation-hover-background, $accent);
		color: var(--tile-navigation-hover-foreground, $accent-foreground);
	}

	&[data-state='open'] {
		background-color: var(--tile-navigation-active-background, color-mix(in srgb, $accent 50%, transparent));
		color: var(--tile-navigation-hover-foreground, $accent-foreground);
	}

	&[data-disabled='true'] {
		pointer-events: none;
		opacity: 0.5;
	}

	&:focus-visible {
		box-shadow: var(--tile-navigation-focus-shadow, none);
	}
}

// 触发器箭头
.chevron {
	position: relative;
	top: 1px;
	width: 0.75rem;
	height: 0.75rem;
	transition: transform $transition-slow;

	&[data-state='open'] {
		transform: rotate(180deg);
	}
}

// 内容面板（默认：相对菜单项下方展开的下拉面板）
.content {
	position: absolute;
	top: 100%;
	left: 0;
	z-index: $z-dropdown;
	min-width: 12rem;
	margin-top: $spacing-1_5;
	border-radius: var(--tile-navigation-panel-radius, $radius);
	border: 1px solid var(--tile-navigation-panel-border, $border);
	background-color: var(--tile-navigation-panel-background, $popover);
	color: var(--tile-navigation-panel-foreground, $popover-foreground);
	padding: var(--tile-navigation-panel-padding, $spacing-2);
	box-shadow: var(--tile-navigation-panel-shadow, $shadow-md);
	outline: none;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
	}

	// 集中式视口模式下内容为正常流布局
	&[data-viewport='true'] {
		position: static;
		width: 100%;
		min-width: 0;
		margin-top: 0;
		border: none;
		padding: 0;
		box-shadow: none;
	}
}

// 集中式视口
.viewport {
	position: absolute;
	top: 100%;
	left: 0;
	z-index: $z-dropdown;
	display: flex;
	justify-content: center;
	margin-top: $spacing-1_5;
	overflow: hidden;
	border-radius: var(--tile-navigation-panel-radius, $radius);
	border: 1px solid var(--tile-navigation-panel-border, $border);
	background-color: var(--tile-navigation-panel-background, $popover);
	color: var(--tile-navigation-panel-foreground, $popover-foreground);
	box-shadow: var(--tile-navigation-panel-shadow, $shadow-md);
	transition:
		opacity $transition-fast,
		visibility $transition-fast,
		transform $transition-fast;

	&[data-state='closed'] {
		opacity: 0;
		visibility: hidden;
		pointer-events: none;
		transform: scale(0.95);
	}

	&[data-state='open'] {
		opacity: 1;
		visibility: visible;
		pointer-events: auto;
		transform: scale(1);
	}
}

// 视口内部容器
.viewportInner {
	position: relative;
	width: 100%;
}

// 指示器
.indicator {
	position: absolute;
	top: 100%;
	z-index: 1;
	display: flex;
	height: $spacing-1_5;
	align-items: flex-end;
	justify-content: center;
	overflow: hidden;
	transition:
		opacity $transition-fast,
		transform $transition-fast;

	&[data-state='hidden'] {
		opacity: 0;
	}

	&[data-state='visible'] {
		opacity: 1;
	}
}

// 指示器箭头
.indicatorArrow {
	position: relative;
	top: 60%;
	width: $spacing-2;
	height: $spacing-2;
	transform: rotate(45deg);
	border-radius: $radius-xs 0 0 0;
	background-color: var(--tile-navigation-panel-border, $border);
	box-shadow: var(--tile-navigation-panel-shadow, $shadow-md);
}

// 链接
.link {
	display: flex;
	flex-direction: column;
	gap: $spacing-1;
	border-radius: var(--tile-navigation-link-radius, $radius-sm);
	padding: var(--tile-navigation-link-padding, $spacing-2);
	font-size: var(--tile-navigation-font-size, $text-sm);
	color: var(--tile-navigation-panel-foreground, $popover-foreground);
	text-decoration: none;
	outline: none;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&:hover {
		background-color: var(--tile-navigation-hover-background, $accent);
		color: var(--tile-navigation-hover-foreground, $accent-foreground);
	}

	&[data-active='true'] {
		background-color: var(--tile-navigation-active-background, color-mix(in srgb, $accent 50%, transparent));
		color: var(--tile-navigation-hover-foreground, $accent-foreground);
	}

	&:focus-visible {
		box-shadow: var(--tile-navigation-focus-shadow, none);
	}
}

@media (prefers-reduced-motion: reduce) {
	.trigger,
	.chevron,
	.viewport,
	.indicator,
	.link {
		transition: none;
	}
}

export {
	NavigationMenu,
	NavigationMenuList,
	NavigationMenuItem,
	NavigationMenuTrigger,
	NavigationMenuContent,
	NavigationMenuViewport,
	NavigationMenuIndicator,
	NavigationMenuLink,
} from './navigation-menu';
